std::vector<Point2d> result;
for (size_t i = 0; i < segments.size(); ++i) {
    for (size_t j = i + 1; j < segments.size(); ++j) {
        const Segment2d& s1 = segments[i];
        const Segment2d& s2 = segments[j];
        double x1 = s1.start.x, y1 = s1.start.y;
        double x2 = s1.end.x, y2 = s1.end.y;
        double x3 = s2.start.x, y3 = s2.start.y;
        double x4 = s2.end.x, y4 = s2.end.y;
        double denom = (y4 - y3) * (x2 - x1) - (x4 - x3) * (y2 - y1);
        if (std::abs(denom) < 1e-10) continue;
        double ua = ((x4 - x3) * (y1 - y3) - (y4 - y3) * (x1 - x3)) / denom;
        double ub = ((x2 - x1) * (y1 - y3) - (y2 - y1) * (x1 - x3)) / denom;
        if (ua >= 0 && ua <= 1 && ub >= 0 && ub <= 1) {
            double ix = x1 + ua * (x2 - x1);
            double iy = y1 + ua * (y2 - y1);
            result.push_back(Point2d(ix, iy));
        }
    }
}
return result;

